const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Bay Dosgris area, south of New Orleans
  const geom = ee.Geometry.Polygon([
    [[-89.35, 29.25], [-89.35, 29.40], [-89.15, 29.40], [-89.15, 29.25], [-89.35, 29.25]]
  ]);

  // 2. Data Acquisition for 1985 (Landsat 5)
  const col1985 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geom)
    .filterDate('1985-01-01', '1985-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1985 = await col1985.size().getInfo();
  console.log(`1985 Images: ${size1985}`);

  if (size1985 === 0) {
    console.log('No data for 1985.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data Acquisition for 2024 (Landsat 9)
  let col2024 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(geom)
    .filterDate('2024-01-01', '2024-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2024 = await col2024.size().getInfo();

  if (size2024 === 0) {
    col2024 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(geom)
      .filterDate('2024-01-01', '2024-12-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    size2024 = await col2024.size().getInfo();
  }

  console.log(`2024 Images: ${size2024}`);

  if (size2024 === 0) {
    console.log('No data for 2024.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Processing function
  function maskClouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const satMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(satMask);
  }

  function calculateWater(image) {
    const green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
    const nir = image.select('SR_B4').multiply(0.0000275).add(-0.2);
    const ndwi = green.subtract(nir).divide(green.add(nir)).rename('NDWI');
    const water = ndwi.gt(0.3);
    return water;
  }

  // 5. Calculate water area for 1985
  const img1985 = col1985.map(maskClouds).median();
  const water1985 = calculateWater(img1985);

  const stats1985 = await water1985.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1985 = stats1985.NDWI_sum || 0;
  const totalPixels1985 = stats1985.NDWI_count || 0;

  if (totalPixels1985 === 0) {
    console.log('No valid pixels for 1985 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  const waterRatio1985 = waterPixels1985 / totalPixels1985;

  // 6. Calculate water area for 2024
  const img2024 = col2024.map(maskClouds).median();
  const water2024 = calculateWater(img2024);

  const stats2024 = await water2024.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2024 = stats2024.NDWI_sum || 0;
  const totalPixels2024 = stats2024.NDWI_count || 0;

  if (totalPixels2024 === 0) {
    console.log('No valid pixels for 2024 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  const waterRatio2024 = waterPixels2024 / totalPixels2024;

  // 7. Validation & Final Answer
  console.log(`1985: Water=${waterPixels1985}, Total=${totalPixels1985}, Ratio=${(waterRatio1985*100).toFixed(2)}%`);
  console.log(`2024: Water=${waterPixels2024}, Total=${totalPixels2024}, Ratio=${(waterRatio2024*100).toFixed(2)}%`);

  if (waterRatio1985 == null || waterRatio2024 == null || isNaN(waterRatio1985) || isNaN(waterRatio2024)) {
    console.log('<answer>C3</answer>');
  } else if (waterRatio2024 > waterRatio1985) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
